def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re

    functions = {"SUM", "MIN", "MAX", "IF"}
    precedence = {
        "=": 0, "<>": 0, "<": 0, "<=": 0, ">": 0, ">=": 0,
        "+": 1, "-": 1,
        "*": 2, "/": 2,
        "neg": 3,
        ":": 4,
    }
    tokenizer = re.compile(r"[0-9]+|[A-Z]+[0-9]*|<>|<=|>=|[^\s]")

    def integer(text):
        negative = text.startswith("-")
        if text[:1] in ("-", "+"):
            text = text[1:]
        value = 0
        for i in range(0, len(text), 9):
            chunk = text[i:i + 9]
            value = value * (10 ** len(chunk)) + int(chunk)
        return -value if negative else value

    def parse(content):
        content = content.strip()
        if not content.startswith("="):
            return ("literal", integer(content))

        values = []
        operators = []
        argument_counts = []
        expecting_operand = True

        def reduce_operator():
            operator = operators.pop()
            if operator == "neg":
                values.append(("neg", values.pop()))
                return

            right = values.pop()
            left = values.pop()
            if operator == ":":
                first, last = left[1], right[1]
                c1, c2 = ord(first[0]), ord(last[0])
                r1, r2 = int(first[1:]), int(last[1:])
                values.append((
                    "range",
                    min(c1, c2), max(c1, c2),
                    min(r1, r2), max(r1, r2),
                ))
            else:
                values.append(("binary", operator, left, right))

        for token in tokenizer.findall(content[1:]):
            if token[0].isdigit():
                values.append(("literal", integer(token)))
                expecting_operand = False
            elif token in functions:
                operators.append(token)
                expecting_operand = True
            elif token[0].isalpha():
                values.append(("reference", token))
                expecting_operand = False
            elif token == "(":
                operators.append("(")
                argument_counts.append(1)
                expecting_operand = True
            elif token == ",":
                while operators[-1] != "(":
                    reduce_operator()
                argument_counts[-1] += 1
                expecting_operand = True
            elif token == ")":
                while operators[-1] != "(":
                    reduce_operator()
                operators.pop()
                count = argument_counts.pop()
                if operators and operators[-1] in functions:
                    function = operators.pop()
                    arguments = tuple(values[-count:])
                    del values[-count:]
                    values.append(("call", function, arguments))
                expecting_operand = False
            else:
                operator = "neg" if token == "-" and expecting_operand else token
                while operators and operators[-1] in precedence:
                    previous = operators[-1]
                    if precedence[previous] < precedence[operator]:
                        break
                    if operator == "neg" and previous == "neg":
                        break
                    reduce_operator()
                operators.append(operator)
                expecting_operand = True

        while operators:
            reduce_operator()
        return values[0]

    parsed = {}
    memo = {}
    active = set()

    def expanded_arguments(arguments):
        for argument in arguments:
            if argument[0] != "range":
                yield argument
                continue

            _, first_col, last_col, first_row, last_row = argument
            for row in range(first_row, last_row + 1):
                for col in range(first_col, last_col + 1):
                    name = chr(col) + str(row)
                    if name in cells:
                        yield ("reference", name)

    def evaluate(name):
        tasks = [("cell", name)]
        values = []

        while tasks:
            task = tasks.pop()
            kind = task[0]

            if kind == "cell":
                name = task[1]
                if name not in cells:
                    values.append(0)
                elif name in memo:
                    values.append(memo[name])
                elif name in active:
                    values.append("#CYCLE!")
                else:
                    if name not in parsed:
                        parsed[name] = parse(cells[name])
                    active.add(name)
                    tasks.append(("finish_cell", name))
                    tasks.append(("node", parsed[name]))

            elif kind == "finish_cell":
                name = task[1]
                memo[name] = values[-1]
                active.remove(name)

            elif kind == "node":
                node = task[1]
                node_kind = node[0]

                if node_kind == "literal":
                    values.append(node[1])
                elif node_kind == "reference":
                    tasks.append(("cell", node[1]))
                elif node_kind == "neg":
                    tasks.append(("negate",))
                    tasks.append(("node", node[1]))
                elif node_kind == "binary":
                    tasks.append(("binary_left", node[1], node[3]))
                    tasks.append(("node", node[2]))
                else:
                    function, arguments = node[1], node[2]
                    if function == "IF":
                        tasks.append(("choose", arguments[1], arguments[2]))
                        tasks.append(("node", arguments[0]))
                    else:
                        iterator = expanded_arguments(arguments)
                        tasks.append(("aggregate_next", function, iterator, None))

            elif kind == "negate":
                value = values.pop()
                values.append(value if isinstance(value, str) else -value)

            elif kind == "binary_left":
                left = values.pop()
                if isinstance(left, str):
                    values.append(left)
                else:
                    tasks.append(("binary_right", task[1], left))
                    tasks.append(("node", task[2]))

            elif kind == "binary_right":
                right = values.pop()
                if isinstance(right, str):
                    values.append(right)
                    continue

                operator, left = task[1], task[2]
                if operator == "+":
                    result = left + right
                elif operator == "-":
                    result = left - right
                elif operator == "*":
                    result = left * right
                elif operator == "/":
                    if right == 0:
                        result = "#DIV/0!"
                    else:
                        result = abs(left) // abs(right)
                        if (left < 0) != (right < 0):
                            result = -result
                elif operator == "=":
                    result = int(left == right)
                elif operator == "<>":
                    result = int(left != right)
                elif operator == "<":
                    result = int(left < right)
                elif operator == "<=":
                    result = int(left <= right)
                elif operator == ">":
                    result = int(left > right)
                else:
                    result = int(left >= right)
                values.append(result)

            elif kind == "choose":
                condition = values.pop()
                if isinstance(condition, str):
                    values.append(condition)
                else:
                    tasks.append(("node", task[1] if condition else task[2]))

            elif kind == "aggregate_next":
                function, iterator, accumulator = task[1:]
                argument = next(iterator, None)
                if argument is None:
                    values.append(0 if accumulator is None else accumulator)
                else:
                    tasks.append((
                        "aggregate_take", function, iterator, accumulator
                    ))
                    tasks.append(("node", argument))

            elif kind == "aggregate_take":
                value = values.pop()
                if isinstance(value, str):
                    values.append(value)
                    continue

                function, iterator, accumulator = task[1:]
                if accumulator is None:
                    accumulator = value
                elif function == "SUM":
                    accumulator += value
                elif function == "MIN":
                    accumulator = min(accumulator, value)
                else:
                    accumulator = max(accumulator, value)
                tasks.append((
                    "aggregate_next", function, iterator, accumulator
                ))

        return values.pop()

    for name in cells:
        if name not in memo:
            evaluate(name)

    return {name: memo[name] for name in cells}
